    """完整计划可负缓存时返回 (负缓存键, 条目)，否则返回 None。

    规则与 PositiveCache 相同，但 ns 中唯一 SOA 的 owner 不受本地 origin
    约束（递归终态的 SOA 可能属于域外权威区）；键仍按本次查询构造。
    """
    if an or rcode not in (0, _RCODE_NXDOMAIN):
        return None
    if len(ns) != 1 or ns[0][1] != _TYPE_SOA:
        return None
